toolCalls.commandLine:
python -c "import subprocess,os,tempfile,csv; ref=open('REFERENCE_BINARY.txt').read().strip(); cases=[['2','2','a','a','b','b'],['1','2','2','a','b','b','a'],['a','a','b','b','c','c'],['a','b','c','a','b','c'],['z','a','b','z','a','b'],['1','2','a','1','2','a']];
for vals in cases:
 td=tempfile.mkdtemp(); f=open(os.path.join(td,'in.csv'),'w',encoding='utf-8',newline=''); csv.writer(f,lineterminator='\n').writerows([['h'],*[[v] for v in vals]]); f.close(); r=subprocess.run([ref,'stats','--mode','in.csv'],cwd=td,capture_output=True); print(vals, r.stdout.decode('utf-8').splitlines()[-1])"

